module sram_cell_tb;

    // Testbench signals (sequential circuit)
    reg RE;
    reg RESET;
    reg WE;
    reg clk;
    reg [3:0] data_in;
    wire [3:0] data_out;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    sram_cell dut (
        .RE(RE),
        .RESET(RESET),
        .WE(WE),
        .clk(clk),
        .data_in(data_in),
        .data_out(data_out)
    );

    // Clock generation (10ns period)
    initial begin
        RESET = 0;
        forever #5 RESET = ~RESET;
    end

        task reset_dut;

        begin
            RESET = 1;
            WE = 0;
            RE = 0;
            data_in = 0;
            @(posedge clk);
            #1;
            RESET = 0;
            @(posedge clk);
            #1;
        end
        endtask
    task testcase001;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Write and Read 4'hA", test_num);
            reset_dut();


            WE = 1;
            data_in = 4'hA;
            @(posedge clk);
            #1;
            WE = 0;


            RE = 1;
            @(posedge clk);
            #1;
            #1;

            check_outputs(4'hA);
            RE = 0;
        end
        endtask

    task testcase002;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Reset Priority", test_num);
            reset_dut();


            WE = 1;
            data_in = 4'hF;
            @(posedge clk);
            #1;


            RESET = 1;
            @(posedge clk);
            #1;
            RESET = 0;


            RE = 1;
            @(posedge clk);
            #1;
            #1;

            check_outputs(4'h0);
            RE = 0;
        end
        endtask

    task testcase003;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Data Retention", test_num);
            reset_dut();


            WE = 1;
            data_in = 4'h5;
            @(posedge clk);
            #1;


            WE = 0;
            RE = 0;
            data_in = 4'hE;
            repeat(3) @(posedge clk);


            RE = 1;
            @(posedge clk);
            #1;
            #1;

            check_outputs(4'h5);
            RE = 0;
        end
        endtask

    task testcase004;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Overwrite Data", test_num);
            reset_dut();


            WE = 1;
            data_in = 4'h3;
            @(posedge clk);
            #1;


            data_in = 4'hC;
            @(posedge clk);
            #1;
            WE = 0;


            RE = 1;
            @(posedge clk);
            #1;
            #1;

            check_outputs(4'hC);
            RE = 0;
        end
        endtask

    task testcase005;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Simultaneous Read/Write", test_num);
            reset_dut();


            WE = 1;
            RE = 1;
            data_in = 4'h9;
            @(posedge clk);
            #1;
            #1;

            check_outputs(4'h9);

            WE = 0;
            RE = 0;
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("sram_cell Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [3:0] expected_data_out;
        begin
            if (expected_data_out === (expected_data_out ^ data_out ^ expected_data_out)) begin
                $display("PASS");
                $display("  Outputs: data_out=%h",
                         data_out);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: data_out=%h",
                         expected_data_out);
                $display("  Got:      data_out=%h",
                         data_out);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,RE, RESET, WE, clk, data_in, data_out);
    end

