module uart_transmitter(  
    input clk,  
    input reset,  
    input [7:0] data_in,  
    input start_transmit,  
    output reg tx,  
    output reg busy  
);  
    reg [3:0] bit_index;  
    reg [15:0] baud_counter;  
    reg sending;  
    parameter BAUD_RATE_DIV = 16'd104; // Example for 9600 baud with 16 MHz clock  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            tx <= 1;  
            busy <= 0;  
            bit_index <= 0;  
            baud_counter <= 0;  
            sending <= 0;  
        end else begin  
            if (start_transmit && !busy) begin  
                busy <= 1;  
                sending <= 1;  
                bit_index <= 0;  
                baud_counter <= 0;  
            end  
            if (sending) begin  
                baud_counter <= baud_counter + 1;  
                if (baud_counter == BAUD_RATE_DIV) begin  
                    baud_counter <= 0;  
                    case (bit_index)  
                        0: tx <= 0; // Start bit  
                        1: tx <= data_in[0];  
                        2: tx <= data_in[1];  
                        3: tx <= data_in[2];  
                        4: tx <= data_in[3];  
                        5: tx <= data_in[4];  
                        6: tx <= data_in[5];  
                        7: tx <= data_in[6];  
                        8: tx <= data_in[7];  
                        9: tx <= 1; // Stop bit  
                        default: sending <= 0;  
                    endcase  
                    bit_index <= bit_index + 1;  
                end  
            end  
            if (bit_index == 10) begin  
                busy <= 0;  
                sending <= 0;  
            end  
        end  
    end  
endmodule

