module WatchdogTimer (  
    input clk,  
    input reset,  
    input kick,  
    output reg timeout  
);  
    parameter TIMEOUT_LIMIT = 5'd15;  
    reg [4:0] counter;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 5'd0;  
            timeout <= 1'b0;  
        end else if (kick) begin  
            counter <= 5'd0;  
            timeout <= 1'b0;  
        end else begin  
            counter <= counter + 1;  
            if (counter >= TIMEOUT_LIMIT) begin  
                timeout <= 1'b1;  
            end  
        end  
    end  
endmodule

