module serializer_32bit (
    input wire clk,
    input wire reset,
    input wire [31:0] data_in,
    output reg data_out
);
    reg [4:0] bit_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            bit_count <= 0;
            data_out <= 0;
        end else begin
            if (bit_count < 32) begin
                data_out <= data_in[bit_count];
                bit_count <= bit_count + 1;
            end else begin
                data_out <= 0; // Optional: output 0 after all bits have been sent
            end
        end
    end
endmodule

