module uart_tx (
    input wire clk,
    input wire reset,
    input wire [7:0] data_in,
    input wire start,
    output reg tx,
    output reg busy
);
    reg [3:0] state;
    reg [3:0] bit_count;
    reg [9:0] shift_reg; // 1 start bit, 8 data bits, 1 stop bit
    parameter IDLE = 4'b0000, START = 4'b0001, DATA = 4'b0010, STOP = 4'b0011;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            tx <= 1; // idle state for tx is high
            busy <= 0;
            bit_count <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        shift_reg <= {1'b1, data_in, 1'b0}; // load data with start and stop bits
                        bit_count <= 0;
                        busy <= 1;
                        state <= START;
                    end
                end

                START: begin
                    tx <= 0; // send start bit
                    state <= DATA;
                end

                DATA: begin
                    tx <= shift_reg[bit_count + 1]; // send each bit
                    if (bit_count < 8) begin
                        bit_count <= bit_count + 1;
                    end else begin
                        state <= STOP;
                    end
                end

                STOP: begin
                    tx <= 1; // send stop bit
                    busy <= 0;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

