module uart_transmitter(  
    input wire clk,  
    input wire reset,  
    input wire [7:0] data_in,  
    input wire transmit,  
    output reg tx,  
    output reg busy  
);  
    reg [3:0] bit_index;  
    reg [9:0] shift_reg; // 1 start bit + 8 data bits + 1 stop bit  
    reg [15:0] baud_counter;  
    parameter BAUD_RATE = 9600;  
    parameter CLOCK_FREQ = 50000000; // Assuming 50 MHz clock  
    parameter BAUD_COUNTER_MAX = CLOCK_FREQ / BAUD_RATE;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            tx <= 1; // Idle state of tx is high  
            busy <= 0;  
            bit_index <= 0;  
            baud_counter <= 0;  
        end else begin  
            if (transmit && !busy) begin  
                busy <= 1;  
                shift_reg <= {1'b1, data_in, 1'b0}; // Start bit, data bits, stop bit  
                bit_index <= 0;  
                baud_counter <= 0;  
            end else if (busy) begin  
                if (baud_counter < BAUD_COUNTER_MAX) begin  
                    baud_counter <= baud_counter + 1;  
                end else begin  
                    baud_counter <= 0;  
                    if (bit_index < 10) begin  
                        tx <= shift_reg[bit_index];  
                        bit_index <= bit_index + 1;  
                    end else begin  
                        busy <= 0; // Transmission complete  
                    end  
                end  
            end  
        end  
    end  
endmodule

